using DomainRelay.Abstractions;using DriveOS.Application.Abstractions.Authentication;using DriveOS.Modules.CurriculumPedagogy.Application.Readiness;using DriveOS.Modules.CurriculumPedagogy.Domain.Readiness;using DriveOS.SharedKernel.Identifiers;using DriveOS.SharedKernel.Results;
namespace DriveOS.Api.Endpoints.CurriculumPedagogy;
internal static class PedagogicalReadinessEndpoints{internal static RouteGroupBuilder MapPedagogicalReadinessEndpoints(this RouteGroupBuilder g){g.MapGet("/training-paths/{trainingPathId:guid}/readiness",Get).RequireAuthorization("Pedagogy.Readiness.Read");g.MapPost("/training-paths/{trainingPathId:guid}/readiness/decisions",Decide).RequireAuthorization("Pedagogy.Readiness.Decide");return g;}private static IResult Fail(Error e)=>Results.Problem(statusCode:e.Type==ErrorType.NotFound?404:e.Type==ErrorType.Conflict?409:400,title:e.Code,detail:e.MessageKey);private static async Task<IResult>Get(Guid trainingPathId,IPedagogicalReadinessReadService r,ICurrentTenant t,CancellationToken ct){if(t.OrganizationId is not{}o)return Results.Unauthorized();var x=await r.GetAsync(o,new TrainingPathId(trainingPathId),ct);return x is null?Results.NotFound():Results.Ok(x);}private static async Task<IResult>Decide(Guid trainingPathId,RecordPedagogicalReadinessDecisionRequest q,IMediator m,ICurrentTenant t,ICurrentUser u,CancellationToken ct){if(t.OrganizationId is not{}o||u.UserId is not{}a)return Results.Unauthorized();if(!Enum.TryParse<PedagogicalReadinessDecisionStatus>(q.Decision,true,out var decision))return Results.BadRequest(new{error="errors.curriculumPedagogy.readiness.invalidDecision"});var x=await m.Send(new RecordPedagogicalReadinessDecisionCommand(o,new TrainingPathId(trainingPathId),decision,q.Rationale,q.Conditions,a),ct);return x.IsSuccess?Results.Created($"/api/pedagogy/training-paths/{trainingPathId}/readiness",new{id=x.Value.Value}):Fail(x.Error);}}
public sealed record RecordPedagogicalReadinessDecisionRequest(string Decision,string Rationale,string? Conditions);
